const rl = require("readline").createInterface({ input: process.stdin });
var iter = rl[Symbol.asyncIterator]();
const readline = async () => (await iter.next()).value;

// 输入输出处理
void (async function () {
  const map = new Map();

  while (true) {
    try {
      const [player, gesture] = (await readline()).split(" ");

      // 如果有人不按套路出，则此局作废
      if (gesture < "A" && gesture > "C") {
        console.log("NULL");
        return;
      }

      // 统计各个手势的人名
      if (!map.has(gesture)) {
        map.set(gesture, []);
      }

      map.get(gesture).push(player);
    } catch (e) {
      break;
    }
  }

  switch (map.size) {
    case 1:
    case 3:
      // 只有一种手势，或者三种手势都有，则平局
      console.log("NULL");
      break;
    case 2:
      let ans;

      if (!map.has("A")) {
        // 没有A手势，只有B、C手势，则B赢
        ans = map.get("B");
      } else if (!map.has("B")) {
        // 没有B手势，只有A、C手势，则C赢
        ans = map.get("C");
      } else {
        // 没有C手势，只有A、B手势，则A赢
        ans = map.get("A");
      }

      ans.sort().forEach((a) => console.log(a));
      break;
  }
})();

