#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_SIZE 1000
#define MAX_NAME_LENGTH 100

int cmp(const void *a, const void *b) {
    return strcmp(((char *) a), ((char *) b));
}

int main() {
    char A[MAX_SIZE][MAX_NAME_LENGTH];
    int A_size = 0;

    char B[MAX_SIZE][MAX_NAME_LENGTH];
    int B_size = 0;

    char C[MAX_SIZE][MAX_NAME_LENGTH];
    int C_size = 0;

    while (1) {
        char s[MAX_NAME_LENGTH * 2] = {'\0'};
        gets(s);

        if (strlen(s) == 0) {
            break;
        }

        char name[MAX_NAME_LENGTH];
        char gesture[2];

        sscanf(s, "%s %s", name, gesture);

        if (gesture[0] == 'A') {
            strcpy(A[A_size++], name);
        } else if (gesture[0] == 'B') {
            strcpy(B[B_size++], name);
        } else if (gesture[0] == 'C') {
            strcpy(C[C_size++], name);
        } else {
            puts("NULL");
            return 0;
        }
    }

    int kinds = 0;
    if (A_size > 0) kinds++;
    if (B_size > 0) kinds++;
    if (C_size > 0) kinds++;

    if (kinds == 1 || kinds == 3) {
        puts("NULL");
    } else {
        if (A_size > 0) {
            if (B_size > 0) {
                qsort(A, A_size, sizeof(A[0]), cmp);

                for (int i = 0; i < A_size; i++) {
                    puts(A[i]);
                }

            } else {
                qsort(C, C_size, sizeof(C[0]), cmp);

                for (int i = 0; i < C_size; i++) {
                    puts(C[i]);
                }
            }
        } else {
            qsort(B, B_size, sizeof(B[0]), cmp);

            for (int i = 0; i < B_size; i++) {
                puts(B[i]);
            }
        }
    }

    return 0;
}
